class SupplierPurchaseScreen extends StatefulWidget { const SupplierPurchaseScreen({super.key,required this.session}); final AuthSession session; @override State<SupplierPurchaseScreen> createState()=>_State(); }
class _State extends State<SupplierPurchaseScreen>{final _api=ApiService();final _db=Supabase.instance.client;bool loading=true;String? error;List<dynamic> suppliers=[],orders=[],deliveries=[],payments=[];
@override void initState(){super.initState();load();}
Future<void> load()async{setState((){loading=true;error=null;});try{final r=await Future.wait([_api.suppliers(widget.session.token),_api.purchaseOrders(widget.session.token),_db.from('purchase_deliveries').select('*, purchase_orders(po_number), materials(name,unit)').order('created_at',ascending:false).limit(100),_db.from('supplier_payments').select('*, suppliers(name), purchase_orders(po_number)').order('created_at',ascending:false).limit(100)]);if(!mounted)return;setState((){suppliers=r[0]as List;orders=r[1]as List;deliveries=r[2]as List;payments=r[3]as List;});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}
